    45→    const userId = decoded.id;
    46→    registerWsClient(userId, ws);
    47→    ws.send(JSON.stringify({ type: 'connected', message: 'متصل بالإشعارات الفورية' }));
    48→    ws.on('close', () => unregisterWsClient(userId));
    49→    ws.on('error', () => unregisterWsClient(userId));
    50→  } catch {
    51→    ws.close();
    52→  }
    53→});
