     9→  { id: 'arrow',  label: '↗',  title: 'سهم' },
    10→  { id: 'rect',   label: '▭',  title: 'مستطيل' },
    11→  { id: 'circle', label: '◯',  title: 'دائرة' },
    12→  { id: 'text',   label: 'T',  title: 'نص' },
    13→  { id: 'eraser', label: '◻',  title: 'ممحاة' },
    14→];
    15→const SIZES = [3, 6, 12, 22];
    16→
    17→export default function DrawingCanvas({ imageUrl, existingNote, allNotes = [], onSave, onClose, blankMode = false }) {
    18→  const canvasRef    = useRef(null);
    19→  const containerRef = useRef(null);
    20→  const historyRef   = useRef([]);
    21→  const historyIdxRef = useRef(-1);
    22→  const drawingRef   = useRef(false);
    23→  const lastPosRef   = useRef(null);
    24→  const startPosRef  = useRef(null);
    25→  const snapshotRef  = useRef(null);
    26→
    27→  const [tool, setTool]           = useState('pen');
    28→  const [color, setColor]         = useState('#ef4444');
    29→  const [size, setSize]           = useState(6);
    30→  const [showImport, setShowImport] = useState(false);
    31→  const [textInput, setTextInput] = useState(null);
    32→  const [textVal, setTextVal]     = useState('');
    33→  const [, tick] = useState(0);
    34→
    35→  const saveHistory = () => {
    36→    const canvas = canvasRef.current;
    37→    if (!canvas) return;
    38→    const dataUrl = canvas.toDataURL('image/png');
    39→    const h = historyRef.current.slice(0, historyIdxRef.current + 1);
    40→    h.push(dataUrl);
    41→    if (h.length > 25) h.shift();
    42→    historyRef.current = h;
    43→    historyIdxRef.current = h.length - 1;
    44→    tick(n => n + 1);
    45→  };
    46→
    47→  useEffect(() => {
    48→    const canvas    = canvasRef.current;
    49→    const container = containerRef.current;
    50→    if (!canvas || !container) return;
    51→    const ctx = canvas.getContext('2d');
    52→
    53→    if (blankMode && !existingNote) {
    54→      const maxW = Math.min(container.clientWidth - 24, 860);
    55→      canvas.width  = maxW;
    56→      canvas.height = 520;
    57→      ctx.fillStyle = '#ffffff';
    58→      ctx.fillRect(0, 0, canvas.width, canvas.height);
    59→      saveHistory();
    60→      return;
    61→    }
    62→
    63→    const src = existingNote || imageUrl;
    64→    const img = new Image();
    65→    img.crossOrigin = 'anonymous';
    66→    img.onload = () => {
    67→      const maxW = Math.min(container.clientWidth - 24, 860);
    68→      const maxH = 520;
    69→      const s = Math.min(maxW / img.naturalWidth, maxH / img.naturalHeight, 1);
    70→      canvas.width  = Math.round(img.naturalWidth  * s);
    71→      canvas.height = Math.round(img.naturalHeight * s);
    72→      if (blankMode) {
    73→        ctx.fillStyle = '#ffffff';
    74→        ctx.fillRect(0, 0, canvas.width, canvas.height);
    75→      }
    76→      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    77→      saveHistory();
    78→    };
    79→    img.onerror = () => {
    80→      canvas.width = 700; canvas.height = 450;
    81→      ctx.fillStyle = '#ffffff';
    82→      ctx.fillRect(0, 0, canvas.width, canvas.height);
    83→      saveHistory();
    84→    };
    85→    const isData = typeof src === 'string' && src.startsWith('data:');
    86→    img.src = isData ? src : (src + (src.includes('?') ? '&' : '?') + 't=' + Date.now());
    87→  }, []);
    88→
    89→  const getPos = (e) => {
    90→    const canvas = canvasRef.current;
    91→    const rect = canvas.getBoundingClientRect();
    92→    const sx = canvas.width  / rect.width;
    93→    const sy = canvas.height / rect.height;
    94→    const cx = e.touches ? e.touches[0].clientX : e.clientX;
    95→    const cy = e.touches ? e.touches[0].clientY : e.clientY;
    96→    return { x: (cx - rect.left) * sx, y: (cy - rect.top) * sy, sx: cx, sy: cy };
    97→  };
    98→
    99→  const drawArrow = (ctx, x1, y1, x2, y2) => {
   100→    const hl = Math.max(16, size * 3.5);
   101→    const angle = Math.atan2(y2 - y1, x2 - x1);
   102→    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
   103→    ctx.strokeStyle = color; ctx.lineWidth = size; ctx.lineCap = 'round'; ctx.stroke();
   104→    ctx.beginPath();
   105→    ctx.moveTo(x2, y2);
   106→    ctx.lineTo(x2 - hl * Math.cos(angle - Math.PI / 6), y2 - hl * Math.sin(angle - Math.PI / 6));
   107→    ctx.lineTo(x2 - hl * Math.cos(angle + Math.PI / 6), y2 - hl * Math.sin(angle + Math.PI / 6));
   108→    ctx.closePath(); ctx.fillStyle = color; ctx.fill();
   109→  };
   110→
   111→  const onMouseDown = (e) => {
   112→    e.preventDefault();
   113→    const pos = getPos(e);
   114→    startPosRef.current = pos;
   115→    lastPosRef.current  = pos;
   116→
   117→    if (tool === 'text') {
   118→      const canvas = canvasRef.current;
   119→      const rect   = canvas.getBoundingClientRect();
   120→      const dsx = pos.x / (canvas.width  / rect.width);
   121→      const dsy = pos.y / (canvas.height / rect.height);
   122→      setTextInput({ screenX: rect.left + dsx, screenY: rect.top + dsy, canvasX: pos.x, canvasY: pos.y });
   123→      setTextVal('');
   124→      return;
   125→    }
   126→
   127→    drawingRef.current = true;
   128→    const canvas = canvasRef.current;
   129→    const ctx    = canvas.getContext('2d');
   130→
   131→    if (['arrow', 'rect', 'circle'].includes(tool)) {
   132→      snapshotRef.current = ctx.getImageData(0, 0, canvas.width, canvas.height);
   133→      return;
   134→    }
   135→
   136→    if (tool === 'pen') {
   137→      ctx.beginPath();
   138→      ctx.arc(pos.x, pos.y, size / 2, 0, Math.PI * 2);
   139→      ctx.fillStyle = color; ctx.fill();
   140→    } else if (tool === 'eraser') {
   141→      ctx.globalCompositeOperation = 'destination-out';
   142→      ctx.beginPath();
   143→      ctx.arc(pos.x, pos.y, size * 2.5, 0, Math.PI * 2);
   144→      ctx.fillStyle = 'rgba(0,0,0,1)'; ctx.fill();
   145→      ctx.globalCompositeOperation = 'source-over';
   146→    }
   147→  };
   148→
   149→  const onMouseMove = (e) => {
   150→    if (!drawingRef.current) return;
   151→    e.preventDefault();
   152→    const pos    = getPos(e);
   153→    const canvas = canvasRef.current;
   154→    const ctx    = canvas.getContext('2d');
   155→
   156→    if (tool === 'pen') {
   157→      ctx.beginPath();
   158→      ctx.moveTo(lastPosRef.current.x, lastPosRef.current.y);
   159→      ctx.lineTo(pos.x, pos.y);
   160→      ctx.strokeStyle = color; ctx.lineWidth = size;
   161→      ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.stroke();
   162→      lastPosRef.current = pos;
   163→    } else if (tool === 'eraser') {
   164→      ctx.globalCompositeOperation = 'destination-out';
   165→      ctx.beginPath();
   166→      ctx.moveTo(lastPosRef.current.x, lastPosRef.current.y);
   167→      ctx.lineTo(pos.x, pos.y);
   168→      ctx.lineWidth = size * 5; ctx.lineCap = 'round'; ctx.stroke();
   169→      ctx.globalCompositeOperation = 'source-over';
   170→      lastPosRef.current = pos;
   171→    } else if (['arrow', 'rect', 'circle'].includes(tool) && snapshotRef.current) {
   172→      ctx.putImageData(snapshotRef.current, 0, 0);
   173→      const s = startPosRef.current;
   174→      ctx.strokeStyle = color; ctx.lineWidth = size; ctx.lineCap = 'round';
   175→      if (tool === 'arrow') {
   176→        drawArrow(ctx, s.x, s.y, pos.x, pos.y);
   177→      } else if (tool === 'rect') {
   178→        ctx.strokeRect(s.x, s.y, pos.x - s.x, pos.y - s.y);
   179→      } else if (tool === 'circle') {
   180→        const rx = (pos.x - s.x) / 2;
   181→        const ry = (pos.y - s.y) / 2;
   182→        ctx.beginPath();
   183→        ctx.ellipse(s.x + rx, s.y + ry, Math.abs(rx), Math.abs(ry), 0, 0, Math.PI * 2);
   184→        ctx.stroke();
   185→      }
   186→    }
   187→  };
   188→
   189→  const onMouseUp = (e) => {
   190→    if (!drawingRef.current) return;
   191→    drawingRef.current = false;
   192→    if (['arrow', 'rect', 'circle'].includes(tool)) {
   193→      const pos    = getPos(e);
   194→      const canvas = canvasRef.current;
   195→      const ctx    = canvas.getContext('2d');
   196→      if (snapshotRef.current) ctx.putImageData(snapshotRef.current, 0, 0);
   197→      const s = startPosRef.current;
   198→      ctx.strokeStyle = color; ctx.lineWidth = size; ctx.lineCap = 'round';
   199→      if (tool === 'arrow') { drawArrow(ctx, s.x, s.y, pos.x, pos.y); }
   200→      else if (tool === 'rect') { ctx.strokeRect(s.x, s.y, pos.x - s.x, pos.y - s.y); }
   201→      else if (tool === 'circle') {
   202→        const rx = (pos.x - s.x) / 2;
   203→        const ry = (pos.y - s.y) / 2;
   204→        ctx.beginPath();
   205→        ctx.ellipse(s.x + rx, s.y + ry, Math.abs(rx), Math.abs(ry), 0, 0, Math.PI * 2);
   206→        ctx.stroke();
   207→      }
   208→    }
   209→    saveHistory();
   210→  };
   211→
   212→  const commitText = () => {
   213→    if (!textInput) return;
   214→    if (textVal.trim()) {
   215→      const ctx      = canvasRef.current.getContext('2d');
   216→      const fontSize = Math.max(16, size * 4);
   217→      ctx.font          = `bold ${fontSize}px Cairo,Arial,sans-serif`;
   218→      ctx.textBaseline  = 'top';
   219→      ctx.shadowColor   = color === '#ffffff' ? '#000' : 'rgba(255,255,255,0.8)';
   220→      ctx.shadowBlur    = 3;
   221→      ctx.fillStyle     = color;
   222→      ctx.fillText(textVal, textInput.canvasX, textInput.canvasY);
   223→      ctx.shadowBlur    = 0;
   224→      saveHistory();
   225→    }
   226→    setTextInput(null); setTextVal('');
   227→  };
   228→
   229→  const undo = () => {
   230→    const idx = historyIdxRef.current;
   231→    if (idx <= 0) return;
   232→    historyIdxRef.current = idx - 1;
   233→    const canvas = canvasRef.current;
   234→    const ctx    = canvas.getContext('2d');
   235→    const img    = new Image();
   236→    img.onload = () => { ctx.clearRect(0, 0, canvas.width, canvas.height); ctx.drawImage(img, 0, 0); };
   237→    img.src = historyRef.current[idx - 1];
   238→    tick(n => n + 1);
   239→  };
   240→
   241→  const handleImport = (data) => {
   242→    const canvas = canvasRef.current;
   243→    const ctx    = canvas.getContext('2d');
   244→    const img    = new Image();
   245→    img.onload = () => {
   246→      ctx.clearRect(0, 0, canvas.width, canvas.height);
   247→      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
   248→      saveHistory(); setShowImport(false);
   249→    };
   250→    img.src = data;
   251→  };
   252→
   253→  const handleSave = () => {
   254→    const canvas = canvasRef.current;
   255→    const exp    = document.createElement('canvas');
   256→    exp.width    = canvas.width;
   257→    exp.height   = canvas.height;
   258→    const ectx   = exp.getContext('2d');
   259→    ectx.fillStyle = '#ffffff';
   260→    ectx.fillRect(0, 0, exp.width, exp.height);
   261→    ectx.drawImage(canvas, 0, 0);
   262→    onSave(exp.toDataURL('image/jpeg', 0.9));
   263→  };
   264→
   265→  const canUndo = historyIdxRef.current > 0;
   266→  const btnBase = { border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', outline: 'none', transition: 'all 0.12s' };
   267→
   268→  return (
   269→    <div className="modal-overlay" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
   270→      <div className="modal" style={{ maxWidth: '97vw', width: 1000, maxHeight: '97vh', display: 'flex', flexDirection: 'column', padding: 0, overflow: 'hidden' }}>
   271→
   272→        {/* ── Header ── */}
   273→        <div className="modal-header" style={{ padding: '11px 16px', flexShrink: 0 }}>
   274→          <span className="modal-title">{blankMode ? '✏️ ملاحظة بالقلم — لوحة حرة' : '✏️ نوت القلم — تعليق على الصورة'}</span>
   275→          <button className="modal-close" onClick={onClose}>×</button>
   276→        </div>
   277→
   278→        {/* ── Toolbar ── */}
   279→        <div style={{ padding: '8px 14px', background: '#f8fafc', borderBottom: '1px solid #e2e8f0', display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', flexShrink: 0 }}>
   280→
   281→          {/* Tools */}
   282→          <div style={{ display: 'flex', gap: 3 }}>
   283→            {TOOLS.map(t => (
   284→              <button key={t.id} title={t.title} onClick={() => setTool(t.id)} style={{ ...btnBase, width: 36, height: 36, borderRadius: 8, border: `2px solid ${tool === t.id ? '#2563eb' : '#e2e8f0'}`, background: tool === t.id ? '#dbeafe' : 'white', fontSize: t.id === 'text' ? 15 : 17, fontWeight: 900, color: tool === t.id ? '#2563eb' : '#64748b', fontFamily: t.id === 'text' ? 'Cairo,serif' : 'inherit' }}>
   285→                {t.label}
   286→              </button>
   287→            ))}
   288→          </div>
   289→
   290→          <div style={{ width: 1, height: 30, background: '#e2e8f0', flexShrink: 0 }} />
   291→
   292→          {/* Colors */}
   293→          <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
   294→            {COLORS.map(c => (
   295→              <button key={c} onClick={() => setColor(c)} style={{ ...btnBase, width: 26, height: 26, borderRadius: '50%', background: c, border: color === c ? '3px solid #2563eb' : '1.5px solid #cbd5e1', transform: color === c ? 'scale(1.2)' : 'scale(1)' }} />
   296→            ))}
   297→          </div>
   298→
   299→          <div style={{ width: 1, height: 30, background: '#e2e8f0', flexShrink: 0 }} />
   300→
   301→          {/* Sizes */}
   302→          <div style={{ display: 'flex', gap: 3, alignItems: 'center' }}>
   303→            {SIZES.map(s => (
   304→              <button key={s} title={`حجم ${s}`} onClick={() => setSize(s)} style={{ ...btnBase, width: 34, height: 34, borderRadius: 8, border: `2px solid ${size === s ? '#2563eb' : '#e2e8f0'}`, background: size === s ? '#dbeafe' : 'white' }}>
   305→                <div style={{ width: Math.min(s + 2, 20), height: Math.min(s + 2, 20), borderRadius: '50%', background: size === s ? '#2563eb' : '#94a3b8' }} />
   306→              </button>
   307→            ))}
   308→          </div>
   309→
   310→          <div style={{ width: 1, height: 30, background: '#e2e8f0', flexShrink: 0 }} />
   311→
   312→          {/* Undo */}
   313→          <button onClick={undo} disabled={!canUndo} title="تراجع" style={{ ...btnBase, width: 36, height: 36, borderRadius: 8, border: '1.5px solid #e2e8f0', background: canUndo ? 'white' : '#f8fafc', cursor: canUndo ? 'pointer' : 'not-allowed', color: canUndo ? '#334155' : '#cbd5e1', fontSize: 19 }}>↩</button>
   314→
   315→          {/* Import */}
   316→          {allNotes.length > 0 && (
   317→            <button onClick={() => setShowImport(v => !v)} style={{ ...btnBase, padding: '5px 10px', borderRadius: 8, border: `1.5px solid ${showImport ? '#2563eb' : '#e2e8f0'}`, background: showImport ? '#dbeafe' : 'white', cursor: 'pointer', fontSize: 12, fontFamily: 'Cairo,sans-serif', fontWeight: 600, color: showImport ? '#2563eb' : '#475569', whiteSpace: 'nowrap', gap: 4 }}>
   318→              📥 استيراد رسمة <span style={{ background: '#2563eb', color: 'white', borderRadius: 99, fontSize: 10, padding: '1px 5px' }}>{allNotes.length}</span>
   319→            </button>
   320→          )}
   321→
   322→          {/* Active tool indicator */}
   323→          <div style={{ marginRight: 'auto', display: 'flex', alignItems: 'center', gap: 6, fontSize: 11, color: '#64748b', fontFamily: 'Cairo,sans-serif' }}>
   324→            <div style={{ width: 16, height: 16, borderRadius: '50%', background: color, border: '1.5px solid #e2e8f0' }} />
   325→            {TOOLS.find(t => t.id === tool)?.title}
   326→          </div>
   327→        </div>
   328→
   329→        {/* ── Import panel ── */}
   330→        {showImport && (
   331→          <div style={{ padding: '10px 14px', background: '#f0f9ff', borderBottom: '1px solid #bfdbfe', display: 'flex', gap: 10, flexWrap: 'wrap', alignItems: 'center', flexShrink: 0 }}>
   332→            <span style={{ fontSize: 12, fontWeight: 700, color: '#1e40af', flexShrink: 0, fontFamily: 'Cairo,sans-serif' }}>اختر رسمة سابقة للاستيراد:</span>
   333→            {allNotes.map((n, i) => (
   334→              <div key={i} onClick={() => handleImport(n.data)} title={'استيراد: ' + n.label} style={{ cursor: 'pointer', border: '2px solid #bfdbfe', borderRadius: 8, overflow: 'hidden', flexShrink: 0, transition: 'border-color 0.15s' }} onMouseEnter={e => e.currentTarget.style.borderColor = '#2563eb'} onMouseLeave={e => e.currentTarget.style.borderColor = '#bfdbfe'}>
   335→                <img src={n.data} alt={n.label} style={{ width: 88, height: 66, objectFit: 'cover', display: 'block' }} />
   336→                <div style={{ fontSize: 9, fontFamily: 'monospace', color: '#475569', padding: '3px 5px', background: 'white', textAlign: 'center', maxWidth: 88, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{n.label}</div>
   337→              </div>
   338→            ))}
   339→          </div>
   340→        )}
   341→
   342→        {/* ── Canvas area ── */}
   343→        <div ref={containerRef} style={{ flex: 1, overflow: 'auto', background: '#1e293b', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 14, minHeight: 280 }}>
   344→          <canvas
   345→            ref={canvasRef}
   346→            style={{ display: 'block', cursor: tool === 'eraser' ? 'cell' : tool === 'text' ? 'text' : 'crosshair', borderRadius: 4, boxShadow: '0 4px 28px rgba(0,0,0,0.55)', maxWidth: '100%' }}
   347→            onMouseDown={onMouseDown}
   348→            onMouseMove={onMouseMove}
   349→            onMouseUp={onMouseUp}
   350→            onMouseLeave={() => { if (drawingRef.current) { drawingRef.current = false; saveHistory(); } }}
   351→            onTouchStart={e => { e.preventDefault(); onMouseDown(e); }}
   352→            onTouchMove={e => { e.preventDefault(); onMouseMove(e); }}
   353→            onTouchEnd={e => { onMouseUp(e); }}
   354→          />
   355→        </div>
   356→
   357→        {/* ── Text input overlay (fixed) ── */}
   358→        {textInput && (
   359→          <input
   360→            autoFocus
   361→            type="text"
   362→            value={textVal}
   363→            onChange={e => setTextVal(e.target.value)}
   364→            onKeyDown={e => { if (e.key === 'Enter') commitText(); if (e.key === 'Escape') { setTextInput(null); setTextVal(''); } }}
   365→            onBlur={commitText}
   366→            placeholder="اكتب نصاً ثم Enter..."
   367→            style={{ position: 'fixed', left: textInput.screenX, top: textInput.screenY - 14, minWidth: 140, padding: '5px 10px', background: 'rgba(255,255,255,0.97)', border: `2px solid ${color}`, borderRadius: 6, fontSize: 14, fontFamily: 'Cairo,sans-serif', color, outline: 'none', zIndex: 99999, boxShadow: '0 2px 18px rgba(0,0,0,0.4)' }}
   368→          />
   369→        )}
   370→
   371→        {/* ── Footer ── */}
   372→        <div style={{ padding: '10px 16px', borderTop: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'white', flexShrink: 0 }}>
   373→          <span style={{ fontSize: 11, color: '#94a3b8', fontFamily: 'Cairo,sans-serif' }}>{blankMode ? 'ارسم ملاحظتك على اللوحة البيضاء ثم احفظ' : 'ارسم على الصورة ثم احفظ • ستظهر في الـ PDF تحت الصورة'}</span>
   374→          <div style={{ display: 'flex', gap: 10 }}>
   375→            <button className="btn btn-secondary" onClick={onClose}>إلغاء</button>
   376→            <button className="btn btn-primary" onClick={handleSave}>💾 حفظ نوت القلم</button>
   377→          </div>
   378→        </div>
   379→      </div>
   380→    </div>
   381→  );
   382→}
   383→

