   365→export async function exportPatientPDF({ patient, sessions = [], ttt = {}, siteInfo = {}, opts = {} }) {
   366→  const allImages = [
   367→    ...(patient.faceImages || []),
   368→    ...(patient.intraOralImages || []),
   369→    ...(patient.xrays || []),
   370→    ...(sessions.flatMap(s => s.images || [])),
   371→  ];
   372→  const imgMap = {};
   373→  await Promise.all(allImages.map(async img => {
   374→    if (img.url) imgMap[img.url] = await imgToBase64(img.url);
   375→  }));
   376→
   377→  const html = buildHTML({ patient, sessions, ttt, siteInfo, opts, imgMap });
   378→  const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
   379→  const blobUrl = URL.createObjectURL(blob);
   380→  return { blobUrl, html };
   381→}
