      ${patient.age ? `<div><div class="pf">${lang === 'ar' ? 'العمر' : 'Age'}</div><div class="pv">${patient.age} ${t.years}</div></div>` : '<div></div>'}
      ${patient.address ? `<div><div class="pf">${t.address}</div><div class="pv">${patient.address}</div></div>` : ''}
